-- 0192: aṣl from every book, batch 12 — each book's own statement (read by its profile; Lane in English), verbatim
-- with block + page and a plain English line; primary = the meaning most books share. Quotes checked against blocks.
-- aslmb_12: aṣl per book for 25 roots that rested on Ibn Fāris alone (AGR:VOC:002/017).
-- Each row: the book's own words as printed + block + page + entry. ONE primary per root, by the reading most books share
-- (tie -> the earliest book). Standalone: INSERT OR IGNORE + guarded UPDATEs; safe to re-run. No row deleted.
-- زيد
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زيد:khalil_kitab_ayn', 'زيد', '6a730520793b47b45666be9e40', 'زِدته زيداً وزيادة. وزاد الشّيءُ نفسُه زيادة', 'I added to it; the thing itself grew', 'الخليل بن أحمد', 'al-Khalīl, Kitāb al-ʿAyn', 170, 'khalil_kitab_ayn', 're_kay_657f0cbf4d50e767', '2680', NULL, 'blk_kay_45224aab9f423087', 0, NULL, 'Marker: head gloss. Reading: adding more.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زيد:jawhari_sihah', 'زيد', '6a730520793b47b45666be9e40', 'الزِيادة: النموُّ', 'increase is growth', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_037f48552842694d', '947', 2, 'blk_sih_29f0d4a4f4500698', 0, NULL, 'Marker: head gloss. Reading: growth. Primary: increase — 8 of 8 books (al-Khalīl blk_kay_45224aab9f423087; al-Jawharī blk_sih_29f0d4a4f4500698; Ibn Fāris blk_mqy_008799d20f121420; Lisān blk_lsn_5e239d596b49007a; al-Miṣbāḥ blk_msb_87a29aca088061f6; al-Qāmūs blk_qms_bdffc63929da3251; Tāj blk_taj_6de5a8f57cce168e; Lane blk_lane_542c929bf4696bb4).', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زيد:ibn_manzur_lisan_arab', 'زيد', '6a730520793b47b45666be9e40', 'الزِّيادة: النُّموّ، وَكَذَلِكَ الزُّوادَةُ. وَالزِّيَادَةُ: خِلَافُ النُّقْصَانِ', 'growth; the opposite of going down', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_5d75ac2e61fe0e02', '20', 1, 'blk_lsn_5e239d596b49007a', 0, NULL, 'Marker: head gloss. Reading: growth.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زيد:fayyumi_misbah_munir', 'زيد', '6a730520793b47b45666be9e40', 'زَادَ الشَّيْءُ يَزِيدُ زَيْدًا وَزِيَادَةً فَهُوَ زَائِدٌ وَزِدْتُهُ أَنَا يُسْتَعْمَلُ لَازِمًا وَمُتَعَدِّيًا', 'the thing grew, and I made it grow', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_a47dcc1de184fd1f', '1348', NULL, 'blk_msb_87a29aca088061f6', 0, NULL, 'Marker: head gloss. Reading: growing.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زيد:qamus_muhit', 'زيد', '6a730520793b47b45666be9e40', 'الزَّيْدُ، بالفتح والكسر والتحريك، والزِّيادَةُ والمَزِيدُ والزَّيْدانُ: بِمَعْنًى', 'these word forms all mean the same', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_170fcb62eb71a02a', NULL, NULL, 'blk_qms_bdffc63929da3251', 0, NULL, 'Marker: Qāmūs gloss. Reading: increase.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زيد:zabidi_taj_arus', 'زيد', '6a730520793b47b45666be9e40', 'كلّ ذالك (بِمَعْنى) ، أَي بمعنَى النُّمُوِّ والزَّكَا', 'all meaning growth and increase', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_36bfa385a9fcd344', '155', 8, 'blk_taj_6de5a8f57cce168e', 0, NULL, 'Marker: Qāmūs gloss + addition. Reading: growth.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زيد:lane_lexicon', 'زيد', '6a730520793b47b45666be9e40', 'It (a thing, Ṣ, Mgh, Mṣb, [as, for ex.,] water, and property, A) increased, or augmented, or grew', 'it increased or grew', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_44046220c6e140c7', '1275', NULL, 'blk_lane_542c929bf4696bb4', 0, NULL, 'Marker: first sense A1. Reading: growing.', 'high', 'active');
