INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زيل:jawhari_sihah', 'زيل', 'eb56f47ab1f2f12a34c8f1d5d5', 'زلت الشئ من مكانه أَزيلُهُ زَيْلاً: لغة في أَزَلْتُهُ', 'I moved the thing from its place', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_d3dacafc5c1e0bba', '3409', 4, 'blk_sih_c31d87389f64f5b0', 0, NULL, 'Marker: head gloss. Reading: removing. Primary: moving away — 4 of 7 books (al-Jawharī blk_sih_c31d87389f64f5b0; Lisān blk_lsn_074ab244eaa27236; al-Miṣbāḥ blk_msb_37b73b3ad3084951; Tāj blk_taj_d2248fa070bccfc9). Other readings: separating: al-Khalīl, Ibn Fāris, Lane.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زيل:ibn_manzur_lisan_arab', 'زيل', 'eb56f47ab1f2f12a34c8f1d5d5', 'زِلْتُ الشيءَ مِنْ مَكَانِهِ أَزِيلُه زَيْلًا: لُغَةٌ فِي أَزَلْته', 'I moved the thing from its place', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_9f3c1f5f1cd11929', '5496', 11, 'blk_lsn_074ab244eaa27236', 0, NULL, 'Marker: head gloss. Reading: removing. Quoted from al-Jawharī via Lisān.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زيل:fayyumi_misbah_munir', 'زيل', 'eb56f47ab1f2f12a34c8f1d5d5', 'زَالَهُ يَزَالُهُ وِزَانُ نَالَ يَنَالُ زِيَالًا نَحَّاهُ', 'he moved it aside', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_360546ccc33443d0', '1351', NULL, 'blk_msb_37b73b3ad3084951', 0, NULL, 'Marker: head gloss. Reading: moving aside.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:زيل:zabidi_taj_arus', 'زيل', 'eb56f47ab1f2f12a34c8f1d5d5', '﴿زَالَهُ عَن مَكانِهِ،﴾ يَزِيلُهُ، ﴿زَيْلاً، لُغَةٌ فِي﴾ أَزَالَهُ', 'he moved it from its place', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_12f0b77ee68f0ee8', '154', 29, 'blk_taj_d2248fa070bccfc9', 0, NULL, 'Marker: Qāmūs gloss. Reading: removing.', 'high', 'active');
