INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سبغ:fayyumi_misbah_munir', 'سبغ', 'b70b76ba999211ef57845775e8', 'سَبَغَ الثَّوْبُ سُبُوغًا مِنْ بَابِ قَعَدَ تَمَّ وَكَمَلَ', 'the garment was full and complete', 'الفيومي', 'al-Fayyūmī, al-Miṣbāḥ al-Munīr', 770, 'fayyumi_misbah_munir', 're_msb_255dc4dc21be572f', '1363', NULL, 'blk_msb_b2ab81ca9f051693', 0, NULL, 'Marker: head gloss. Reading: complete.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سبغ:qamus_muhit', 'سبغ', 'b70b76ba999211ef57845775e8', 'سَبَغَ الشيءُ سُبُوغاً: طالَ إلى الأَرْضِ', 'the thing hung long to the ground', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_1f61e78848a13f34', NULL, NULL, 'blk_qms_5599acc906d1416c', 0, NULL, 'Marker: Qāmūs gloss. Reading: long to the ground. Differs from the main reading (full, ample).', 'high', 'active');
