INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سبل:lane_lexicon', 'سبل', 'f412292a905c9f4007ee241064', 'سَبَلٌ A thing that one has let loose, let down, let fall, or made to hang down, and to drag [on the ground]', 'something let down to hang', 'لين', 'E. W. Lane, Arabic-English Lexicon', NULL, 'lane_lexicon', 're_lane_dac7162bea892d33', '1301', NULL, 'blk_lane_f565c91bdbb7b143', 0, NULL, 'Marker: first noun sense (his verbs start at form 2, the ''God''s cause'' sense). Reading: hanging down. Differs from the main reading (road, stretching out).', 'medium', 'active');
