INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سجد:jawhari_sihah', 'سجد', '587d2efd320fe2ae9d58738347', 'سَجَدَ: خضع', 'he bowed humbly', 'الجوهري', 'al-Jawharī, al-Ṣiḥāḥ', 393, 'jawhari_sihah', 're_sih_8dc817bd50727c39', '951', 2, 'blk_sih_b1315b2fd012605e', 0, NULL, 'Marker: head gloss. Reading: humbling oneself. Primary: bowing low — 7 of 9 books (al-Jawharī blk_sih_b1315b2fd012605e; Ibn Fāris blk_mqy_dc80bad6d6de758d; al-Rāghib blk_mfr_d483fa3ed15c3fa4; Lisān blk_lsn_58458ed101633ea7; al-Qāmūs blk_qms_4ff0f861a64c844f; Tāj blk_taj_5d109c1746104a59; Lane blk_lane_35941958ec3167a1). Other readings: lowered gaze: al-Khalīl, Ibn Durayd.', 'high', 'active');
