INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سجد:ibn_manzur_lisan_arab', 'سجد', '587d2efd320fe2ae9d58738347', 'سَجَدَ يَسْجُدُ سُجُودًا وَضَعَ جَبْهَتَهُ بالأَرض', 'he put his forehead on the ground', 'ابن منظور', 'Ibn Manẓūr, Lisān al-ʿArab', 711, 'ibn_manzur_lisan_arab', 're_lsn_90ff702db616ec21', '1646', 3, 'blk_lsn_58458ed101633ea7', 0, NULL, 'Marker: first gloss after the Ṭayyiʾ note. Reading: forehead to ground. Quoted from Ibn Sīda via Lisān.', 'medium', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سجد:qamus_muhit', 'سجد', '587d2efd320fe2ae9d58738347', 'سَجَدَ: خَضَعَ، وانْتَصَبَ، ضِدٌّ', 'he bowed humbly; also stood upright', 'الفيروزآبادي', 'al-Fīrūzābādī, al-Qāmūs', 817, 'qamus_muhit', 're_qms_8f1502f5eb70c8a4', NULL, NULL, 'blk_qms_4ff0f861a64c844f', 0, NULL, 'Marker: Qāmūs gloss. Reading: humbling oneself.', 'high', 'active');
INSERT OR IGNORE INTO ar_ling_root_asl (id, root_norm, root_id, statement_ar, statement_en, authority_ar, authority_en, death_hijri, source_slug, lexicon_entry_id, page_ref, volume_no, block_id, is_primary, narrows_id, note_md, confidence, status) VALUES ('ASL:سجد:zabidi_taj_arus', 'سجد', '587d2efd320fe2ae9d58738347', '(سَجَدَ: خَضَعَ) ، وَمِنْه سُجُودُ الصَّلاةِ، وَهُوَ وَضْعُ الجَبْهةِ على الأَرض', 'he bowed humbly; hence bowing in prayer', 'الزبيدي', 'al-Zabīdī, Tāj al-ʿArūs', 1205, 'zabidi_taj_arus', 're_taj_b4f77156b55ed233', '172', 8, 'blk_taj_5d109c1746104a59', 0, NULL, 'Marker: Qāmūs gloss + addition. Reading: humbling oneself.', 'high', 'active');
